\u043d\\u0435 \\u043a\\u0430\\u0436\\u0434\\u043e\\u0433\\u043e \\u0441\\u043a\\u043e\\u043b\\u044c\\u0437\\u044f\\u0449\\u0435\\u0433\\u043e \\u043e\\u043a\\u043d\\u0430, \\u0438\\u0441\\u043a\\u043b\\u044e\\u0447\\u0430\\u044e\\u0449\\u0430\\u044f data leakage \\u0438 \\u0441\\u043c\\u044f\\u0433\\u0447\\u0430\\u044e\\u0449\\u0430\\u044f \\u043d\\u0435\\u0441\\u0442\\u0430\\u0446\\u0438\\u043e\\u043d\\u0430\\u0440\\u043d\\u043e\\u0441\\u0442\\u044c \\u0440\\u0430\\u0441\\u043f\\u0440\\u0435\\u0434\\u0435\\u043b\\u0435\\u043d\\u0438\\u044f.\\n- **\\u0420\\u0430\\u0437\\u043c\\u0435\\u0440 \\u0432\\u0445\\u043e\\u0434\\u043d\\u043e\\u0433\\u043e \\u043e\\u043a\\u043d\\u0430 (Lookback window $L$):** \\u0424\\u0438\\u043a\\u0441\\u0438\\u0440\\u0443\\u0435\\u0442\\u0441\\u044f $L = 720$ \\u0448\\u0430\\u0433\\u043e\\u0432 (7.5 \\u0441\\u0443\\u0442\\u043e\\u043a). \\u042d\\u0442\\u043e \\u0433\\u0430\\u0440\\u0430\\u043d\\u0442\\u0438\\u0440\\u0443\\u0435\\u0442, \\u0447\\u0442\\u043e \\u0432 \\u043e\\u043a\\u043d\\u0435 \\u0441\\u043e\\u0434\\u0435\\u0440\\u0436\\u0438\\u0442\\u0441\\u044f \\u043f\\u043e\\u043b\\u043d\\u044b\\u0439 \\u043d\\u0435\\u0434\\u0435\\u043b\\u044c\\u043d\\u044b\\u0439 \\u0446\\u0438\\u043a\\u043b ($672 < 720$), \\u0447\\u0442\\u043e \\u043d\\u0435\\u043e\\u0431\\u0445\\u043e\\u0434\\u0438\\u043c\\u043e \\u0434\\u043b\\u044f \\u043a\\u043e\\u0440\\u0440\\u0435\\u043a\\u0442\\u043d\\u043e\\u0433\\u043e \\u0438\\u0441\\u0441\\u043b\\u0435\\u0434\\u043e\\u0432\\u0430\\u043d\\u0438\\u044f \\u043f\\u0435\\u0440\\u0438\\u043e\\u0434\\u043e\\u0432 \\u0432\\u043f\\u043b\\u043e\\u0442\\u044c \\u0434\\u043e \\u043d\\u0435\\u0434\\u0435\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e.\\n- **\\u0413\\u043e\\u0440\\u0438\\u0437\\u043e\\u043d\\u0442\\u044b \\u043f\\u0440\\u043e\\u0433\\u043d\\u043e\\u0437\\u0430 ($H$):** \\u0421\\u0435\\u0442\\u043a\\u0430 \\u0431\\u0435\\u043d\\u0447\\u043c\\u0430\\u0440\\u043a\\u0430 $H \\\\in \\\\{96, 192, 336, 720\\\\}$ (\\u0441\\u043e\\u043e\\u0442\\u0432\\u0435\\u0442\\u0441\\u0442\\u0432\\u0443\\u0435\\u0442 1 \\u0441\\u0443\\u0442\\u043a\\u0430\\u043c, 2 \\u0441\\u0443\\u0442\\u043a\\u0430\\u043c, 3.5 \\u0441\\u0443\\u0442\\u043a\\u0430\\u043c \\u0438 7.5 \\u0441\\u0443\\u0442\\u043a\\u0430\\u043c).\\n\\n### 2.2. \\u0424\\u0430\\u043a\\u0442\\u043e\\u0440\\u043d\\u044b\\u0439 \\u043f\\u043b\\u0430\\u043d: \\u0421\\u0435\\u0442\\u043a\\u0430 \\u043d\\u0430\\u0441\\u0442\\u0440\\u043e\\u0435\\u043a \\u043f\\u0435\\u0440\\u0438\\u043e\\u0434\\u0430 (Period Settings Grid)\\n\\n\\u042d\\u043a\\u0441\\u043f\\u0435\\u0440\\u0438\\u043c\\u0435\\u043d\\u0442 \\u0441\\u0442\\u0440\\u043e\\u0438\\u0442\\u0441\\u044f \\u043f\\u043e \\u0441\\u0445\\u0435\\u043c\\u0435 \\u043f\\u043e\\u043b\\u043d\\u043e\\u0433\\u043e \\u0444\\u0430\\u043a\\u0442\\u043e\\u0440\\u043d\\u043e\\u0433\\u043e \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d\\u0430 ($N_{configs} \\\\times N_{horizons} \\\\times N_{seeds}$):\\n\\n| \\u0413\\u0440\\u0443\\u043f\\u043f\\u0430 \\u043a\\u043e\\u043d\\u0444\\u0438\\u0433\\u0443\\u0440\\u0430\\u0446\\u0438\\u0439 | \\u0418\\u0434\\u0435\\u043d\\u0442\\u0438\\u0444\\u0438\\u043a\\u0430\\u0442\\u043e\\u0440 | \\u041d\\u0430\\u0441\\u0442\\u0440\\u043e\\u0439\\u043a\\u0430 \\u043f\\u0435\\u0440\\u0438\\u043e\\u0434\\u043e\\u0432 ($P$) | \\u041d\\u0430\\u0437\\u043d\\u0430\\u0447\\u0435\\u043d\\u0438\\u0435 / \\u041e\\u0431\\u043e\\u0441\\u043d\\u043e\\u0432\\u0430\\u043d\\u0438\\u0435 |\\n| :--- | :--- | :--- | :--- |\\n| **A. Monoperiodic (\\u0424\\u0438\\u0437\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0435)** | `P-96` | $P = [96]$ | \\u0411\\u0430\\u0437\\u043e\\u0432\\u044b\\u0439 \\u0441\\u0443\\u0442\\u043e\\u0447\\u043d\\u044b\\u0439 \\u0446\\u0438\\u043a\\u043b (24 \\u0447) |\\n| | `P-672` | $P = [672]$ | \\u041d\\u0435\\u0434\\u0435\\u043b\\u044c\\u043d\\u044b\\u0439 \\u0446\\u0438\\u043a\\u043b (7 \\u0434\\u043d\\u0435\\u0439) |\\n| | `P-48` | $P = [48]$ | \\u041f\\u043e\\u043b\\u0443\\u0441\\u0443\\u0442\\u043e\\u0447\\u043d\\u0430\\u044f \\u0441\\u0443\\u0431\\u0433\\u0430\\u0440\\u043c\\u043e\\u043d\\u0438\\u043a\\u0430 (12 \\u0447) |\\n| | `P-32` | $P = [32]$ | 8-\\u0447\\u0430\\u0441\\u043e\\u0432\\u0430\\u044f \\u0441\\u0443\\u0431\\u0433\\u0430\\u0440\\u043c\\u043e\\u043d\\u0438\\u043a\\u0430 |\\n| **B. Multi-periodic (\\u041a\\u043e\\u043c\\u0431\\u0438\\u043d\\u0430\\u0446\\u0438\\u0438)** | `Multi-DailyWeekly` | $P = [96, 672]$ | \\u0421\\u043e\\u0432\\u043c\\u0435\\u0449\\u0435\\u043d\\u0438\\u0435 \\u0434\\u043d\\u044f \\u0438 \\u043d\\u0435\\u0434\\u0435\\u043b\\u0438 |\\n| | `Multi-FullHarmonic`| $P = [32, 48, 96, 672]$ | \\u041f\\u043e\\u043b\\u043d\\u044b\\u0439 \\u0441\\u043f\\u0435\\u043a\\u0442\\u0440 \\u0434\\u043e\\u043c\\u0438\\u043d\\u0438\\u0440\\u0443\\u044e\\u0449\\u0438\\u0445 \\u0433\\u0430\\u0440\\u043c\\u043e\\u043d\\u0438\\u043a |\\n| | `Multi-SubDaily` | $P = [32, 48, 96]$ | \\u0422\\u043e\\u043b\\u044c\\u043a\\u043e \\u0432\\u043d\\u0443\\u0442\\u0440\\u0438\\u0441\\u0443\\u0442\\u043e\\u0447\\u043d\\u044b\\u0435 \\u0438 \\u0441\\u0443\\u0442\\u043e\\u0447\\u043d\\u044b\\u0435 |\\n| **C. Automated (Data-driven FFT)** | `FFT-Top1` | $k=1$ \\u043f\\u043e \\u0441\\u043f\\u0435\\u043a\\u0442\\u0440\\u0430\\u043b\\u044c\\u043d\\u043e\\u0439 \\u043c\\u043e\\u0449\\u043d\\u043e\\u0441\\u0442\\u0438 | \\u0414\\u0438\\u043d\\u0430\\u043c\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0439 \\u0434\\u043e\\u043c\\u0438\\u043d\\u0438\\u0440\\u0443\\u044e\\u0449\\u0438\\u0439 \\u043f\\u0435\\u0440\\u0438\\u043e\\u0434 |\\n| | `FFT-Top3` | $k=3$ \\u043f\\u043e \\u0441\\u043f\\u0435\\u043a\\u0442\\u0440\\u0430\\u043b\\u044c\\u043d\\u043e\\u0439 \\u043c\\u043e\\u0449\\u043d\\u043e\\u0441\\u0442\\u0438 | \\u0410\\u0434\\u0430\\u043f\\u0442\\u0438\\u0432\\u043d\\u0430\\u044f \\u043c\\u0443\\u043b\\u044c\\u0442\\u0438\\u043f\\u0435\\u0440\\u0438\\u043e\\u0434\\u0438\\u0447\\u043d\\u043e\\u0441\\u0442\\u044c |\\n| | `FFT-Top5` | $k=5$ \\u043f\\u043e \\u0441\\u043f\\u0435\\u043a\\u0442\\u0440\\u0430\\u043b\\u044c\\u043d\\u043e\\u0439 \\u043c\\u043e\\u0449\\u043d\\u043e\\u0441\\u0442\\u0438 | \\u0420\\u0430\\u0441\\u0448\\u0438\\u0440\\u0435\\u043d\\u043d\\u044b\\u0439 \\u0441\\u043f\\u0435\\u043a\\u0442\\u0440 (\\u043f\\u0440\\u043e\\u0432\\u0435\\u0440\\u043a\\u0430 \\u043d\\u0430 \\u043f\\u0435\\u0440\\u0435\\u043e\\u0431\\u0443\\u0447\\u0435\\u043d\\u0438\\u0435 \\u043a \\u0448\\u0443\\u043c\\u0443) |\\n| **D. Sensitivity / Perturbation** | `Perturb-P95` | $P = [95]$ | \\u0414\\u0435\\u0432\\u0438\\u0430\\u0446\\u0438\\u044f $-1$ \\u0448\\u0430\\u0433 ($-15$ \\u043c\\u0438\\u043d) |\\n| | `Perturb-P97` | $P = [97]$ | \\u0414\\u0435\\u0432\\u0438\\u0430\\u0446\\u0438\\u044f $+1$ \\u0448\\u0430\\u0433 ($+15$ \\u043c\\u0438\\u043d) |\\n| | `Perturb-P90` | $P = [90]$ | \\u0421\\u043c\\u0435\\u0449\\u0435\\u043d\\u0438\\u0435 \\u043d\\u0430 1.5 \\u0447\\u0430\\u0441\\u0430 |\\n| | `Perturb-P102` | $P = [102]$ | \\u0421\\u043c\\u0435\\u0449\\u0435\\u043d\\u0438\\u0435 \\u043d\\u0430 1.5 \\u0447\\u0430\\u0441\\u0430 |\\n| **E. Controls** | `Ctrl-Identity` | $P = [1]$ | Flat / \\u0431\\u0435\\u0437 \\u043f\\u0435\\u0440\\u0438\\u043e\\u0434\\u0438\\u0447\\u0435\\u0441\\u043a\\u043e\\u0439 \\u0434\\u0435\\u043a\\u043e\\u043c\\u043f\\u043e\\u0437\\u0438\\u0446\\u0438\\u0438 |\\n| | `Ctrl-RandomPrime`| $P = [53]$ | \\u041f\\u0435\\u0440\\u0438\\u043e\\u0434, \\u043d\\u0435 \\u0434\\u0435\\u043b\\u044f\\u0449\\u0438\\u0439 96 \\u0438 672 (\\u043f\\u0441\\u0435\\u0432\\u0434\\u043e\\u0441\\u043b\\u0443\\u0447\\u0430\\u0439\\u043d\\u044b\\u0439) |\\n| | `Ctrl-Incommensurate` | $P = [137, 251]$ | \\u0414\\u0432\\u0430 \\u043d\\u0435\\u0441\\u043e\\u0438\\u0437\\u043c\\u0435\\u0440\\u0438\\u043c\\u044b\\u0445 \\u043f\\u0440\\u043e\\u0441\\u0442\\u044b\\u0445 \\u043f\\u0435\\u0440\\u0438\\u043e\\u0434\\u0430 |\\n\\n### 2.3. \\u041a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u044c \\u0433\\u0438\\u043f\\u0435\\u0440\\u043f\\u0430\\u0440\\u0430\\u043c\\u0435\\u0442\\u0440\\u043e\\u0432 \\u0438 \\u0443\\u0441\\u043b\\u043e\\u0432\\u0438\\u044f \\u043e\\u0431\\u0443\\u0447\\u0435\\u043d\\u0438\\u044f\\n\\u0414\\u043b\\u044f \\u0438\\u0441\\u043a\\u043b\\u044e\\u0447\\u0435\\u043d\\u0438\\u044f \\u043a\\u043e\\u043d\\u0444\\u0430\\u0443\\u043d\\u0434\\u0438\\u043d\\u0433\\u0430 \\u0432\\u0441\\u0435 \\u043f\\u0440\\u043e\\u0447\\u0438\\u0435 \\u0433\\u0438\\u043f\\u0435\\u0440\\u043f\\u0430\\u0440\\u0430\\u043c\\u0435\\u0442\\u0440\\u044b \\u043c\\u043e\\u0434\\u0435\\u043b\\u0438 \\u0441\\u0442\\u0440\\u043e\\u0433\\u043e \\u0437\\u0430\\u043c\\u043e\\u0440\\u0430\\u0436\\u0438\\u0432\\u0430\\u044e\\u0442\\u0441\\u044f \\u0432\\u043e \\u0432\\u0441\\u0435\\u0445 \\u0437\\u0430\\u043f\\u0443\\u0441\\u043a\\u0430\\u0445:\\n- \\u041e\\u043f\\u0442\\u0438\\u043c\\u0438\\u0437\\u0430\\u0442\\u043e\\u0440: AdamW ($\\\\beta_1 = 0.9, \\\\beta_2 = 0.999$, weight decay = $10^{-4}$).\\n- \\u041d\\u0430\\u0447\\u0430\\u043b\\u044c\\u043d\\u044b\\u0439 Learning Rate: $\\\\eta = 10^{-3}$ \\u0441 \\u043a\\u043e\\u0441\\u0438\\u043d\\u0443\\u0441\\u043d\\u044b\\u043c \\u0440\\u0430\\u0441\\u043f\\u0438\\u0441\\u0430\\u043d\\u0438\\u0435\\u043c (CosineAnnealingLR, $\\\\eta_{min} = 10^{-6}$).\\n- \\u0420\\u0430\\u0437\\u043c\\u0435\\u0440 \\u0431\\u0430\\u0442\\u0447\\u0430: 32.\\n- \\u0424\\u0443\\u043d\\u043a\\u0446\\u0438\\u044f \\u043f\\u043e\\u0442\\u0435\\u0440\\u044c: MSE Loss: $\\\\mathcal{L}_{MSE} = \\\\frac{1}{H \\\\cdot C}\\\\sum_{t=1}^H \\\\sum_{i=1}^C (y_{t,i} - \\\\hat{y}_{t,i})^2$.\\n- \\u0420\\u0435\\u0433\\u0443\\u043b\\u044f\\u0440\\u0438\\u0437\\u0430\\u0446\\u0438\\u044f \\u0438 Early Stopping: \\u0442\\u0435\\u0440\\u043f\\u0435\\u043d\\u0438\\u0435 (patience) = 5 \\u044d\\u043f\\u043e\\u0445 \\u043f\\u043e validation loss, \\u043c\\u0430\\u043a\\u0441\\u0438\\u043c\\u0430\\u043b\\u044c\\u043d\\u043e\\u0435 \\u0447\\u0438\\u0441\\u043b\\u043e \\u044d\\u043f\\u043e\\u0445 = 30.\\n- \\u0412\\u043e\\u0441\\u043f\\u0440\\u043e\\u0438\\u0437\\u0432\\u043e\\u0434\\u0438\\u043c\\u043e\\u0441\\u0442\\u044c: \\u043a\\u0430\\u0436\\u0434\\u044b\\u0439 \\u044d\\u043a\\u0441\\u043f\\u0435\\u0440\\u0438\\u043c\\u0435\\u043d\\u0442 \\u043f\\u0440\\u043e\\u0433\\u043e\\u043d\\u044f\\u0435\\u0442\\u0441\\u044f \\u043d\\u0430 **5 \\u043d\\u0435\\u0437\\u0430\\u0432\\u0438\\u0441\\u0438\\u043c\\u044b\\u0445 \\u0441\\u043b\\u0443\\u0447\\u0430\\u0439\\u043d\\u044b\\u0445 \\u0441\\u0438\\u0434\\u0430\\u0445** ($seed \\\\in \\\\{42, 100, 2024, 777, 1337\\\\}$) \\u0434\\u043b\\u044f \\u0444\\u0438\\u043a\\u0441\\u0430\\u0446\\u0438\\u0438 \\u0438\\u043d\\u0438\\u0446\\u0438\\u0430\\u043b\\u0438\\u0437\\u0430\\u0446\\u0438\\u0438 \\u0432\\u0435\\u0441\\u043e\\u0432 \\u0438 \\u043f\\u043e\\u0440\\u044f\\u0434\\u043a\\u0430 \\u0431\\u0430\\u0442\\u0447\\u0435\\u0439.\\n\\n---\\n\\n## 3. \\u0421\\u0438\\u0441\\u0442\\u0435\\u043c\\u0430 \\u043a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u0435\\u0439 \\u0438 \\u0430\\u0431\\u043b\\u044f\\u0446\\u0438\\u0439 (Controls & Ablation)\\n\\n1. **Negative Controls (\\u041e\\u0442\\u0440\\u0438\\u0446\\u0430\\u0442\\u0435\\u043b\\u044c\\u043d\\u044b\\u0439 \\u043a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u044c):**\\n   - `Ctrl-Identity` ($P=1$): \\u043e\\u0442\\u043a\\u043b\\u044e\\u0447\\u0430\\u0435\\u0442 \\u043f\\u0435\\u0440\\u0438\\u043e\\u0434\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0439 \\u0444\\u043e\\u043b\\u0434\\u0438\\u043d\\u0433/\\u0447\\u0430\\u0441\\u0442\\u043e\\u0442\\u043d\\u0443\\u044e \\u0444\\u0438\\u043b\\u044c\\u0442\\u0440\\u0430\\u0446\\u0438\\u044e. \\u041f\\u043e\\u0437\\u0432\\u043e\\u043b\\u044f\\u0435\\u0442 \\u0438\\u0437\\u043c\\u0435\\u0440\\u0438\\u0442\\u044c \\u0447\\u0438\\u0441\\u0442\\u044b\\u0439 \\u0432\\u044b\\u0438\\u0433\\u0440\\u044b\\u0448 \\u043e\\u0442 \\u0432\\u043a\\u043b\\u044e\\u0447\\u0435\\u043d\\u0438\\u044f \\u043c\\u0435\\u0445\\u0430\\u043d\